class Solution:
    def evalMinStack(self, ops: List[str], vals: List[List[int]]) -> List[Any]:
        stack = []
        min_stack = []
        res = []
        for op, val in zip(ops, vals):
            if op == "push":
                v = val[0]
                stack.append(v)
                min_val = min(v, min_stack[-1] if min_stack else v)
                min_stack.append(min_val)
                res.append(None)
            elif op == "pop":
                stack.pop()
                min_stack.pop()
                res.append(None)
            elif op == "top":
                res.append(stack[-1])
            elif op == "getMin":
                res.append(min_stack[-1])
        return res

reference_solution.javascript:
function evalMinStack(ops, vals) {
    const stack = [];
    const minStack = [];
    const res = [];
    for (let i = 0; i < ops.length; i++) {
        const op = ops[i];
        const v = vals[i];
        if (op === "push") {
            const val = v[0];
            stack.push(val);
            const minVal = minStack.length === 0 ? val : Math.min(val, minStack[minStack.length - 1]);
            minStack.push(minVal);
            res.push(null);
        } else if (op === "pop") {
            stack.pop();
            minStack.pop();
            res.push(null);
        } else if (op === "top") {
            res.push(stack[stack.length - 1]);
        } else if (op === "getMin") {
            res.push(minStack[minStack.length - 1]);
        }
    }
    return res;
}
